/**
 * Sinhala Unicode <-> legacy "FM" ASCII font encoding.
 *
 * FM fonts (FM Abhaya, FM Malithi, FM Gemunu, FM Derana, ...) draw Sinhala
 * glyphs at ASCII/Latin-1 code points. Text for such a font must be stored in
 * visual (glyph) order: pre-base vowel signs (ෙ, ෛ) come *before* the
 * consonant cluster, and the al-lakuna / aela-pilla parts of split vowels
 * come after it.
 *
 * The mapping data lives in ./fm-table.json, generated by the Python service
 * (python/keyframe_sinhala/table.py) and verified against the real FM font
 * files (python -m keyframe_sinhala.verify). python/keyframe_sinhala/fm.py is a
 * line-by-line port of this algorithm; python/tests/golden.json is checked
 * against both.
 */

import table from './fm-table.json';

type Pair = readonly [unicode: string, fm: string];

const ZWJ = '‍';
const ZWNJ = '‌';
const HAL = '්'; // ් al-lakuna / virama

const pairs = (rows: readonly (readonly string[])[]): readonly Pair[] => rows.map((r) => [r[0], r[1]] as const);

/** Consonants. */
export const FM_CONSONANTS: readonly Pair[] = pairs(table.consonants);
/** Independent vowels. ඓ is drawn as the kombuva glyph + එ. */
export const FM_INDEPENDENT_VOWELS: readonly Pair[] = pairs(table.independentVowels);
/** Post-base dependent vowel signs (and the al-lakuna). */
export const FM_VOWEL_SIGNS: readonly Pair[] = pairs(table.vowelSigns);
/** Split / pre-base vowel signs: [unicode, prefix, suffix]; FM order is prefix + cluster + suffix. */
export const FM_PRE_BASE_SIGNS: readonly (readonly [string, string, string])[] = table.preBase.map(
  (r) => [r[0], r[1], r[2]] as const,
);
/** Consonant + vowel-sign pairs drawn with a dedicated glyph (bare consonants only). */
export const FM_SPECIAL_SYLLABLES: readonly Pair[] = pairs(table.specialSyllables);
/** Touching conjuncts (C ් ZWJ C2) drawn with a half-form glyph; used as a cluster base. */
export const FM_CONJUNCTS: readonly Pair[] = pairs(table.conjuncts);
/** ASCII punctuation is drawn at other code points in FM fonts. [unicode, fm] */
export const FM_PUNCTUATION: readonly Pair[] = pairs(table.punctuation);

export const FM_ANUSVARA = table.signs.anusvara; // ං
export const FM_VISARGA = table.signs.visarga; // ඃ
export const FM_RAKARANSAYA = table.signs.rakaransaya; // ්‍ර  (written after the consonant)
export const FM_YANSAYA = table.signs.yansaya; // ්‍ය  (written after the consonant)
export const FM_REPAYA = table.signs.repaya; // ර්‍ + C  (written after the consonant cluster)

// ---------------------------------------------------------------------------

const consMap = new Map(FM_CONSONANTS);
const ivMap = new Map(FM_INDEPENDENT_VOWELS);
const vsMap = new Map(FM_VOWEL_SIGNS);
const preMap = new Map(FM_PRE_BASE_SIGNS.map(([u, p, s]) => [u, [p, s] as const]));
const specialMap = new Map(FM_SPECIAL_SYLLABLES);
// FM fonts draw many consonant + sign pairs (ම් රි වි ඩ් …) as one glyph; the decoder already knows them, so write them the same way.
for (const [fm, u] of table.decodeAliases) if (u.length === 2 && consMap.has(u[0]) && vsMap.has(u[1]) && !specialMap.has(u)) specialMap.set(u, fm);
const conjMap = new Map(FM_CONJUNCTS);
const punctMap = new Map(FM_PUNCTUATION);

const SINHALA_RE = /[඀-෿]/;

export function hasSinhala(text: string): boolean {
  return SINHALA_RE.test(text);
}

function isSinhalaChar(ch: string): boolean {
  return SINHALA_RE.test(ch) || ch === ZWJ || ch === ZWNJ;
}

/**
 * Convert Unicode Sinhala to FM glyph encoding. Non-Sinhala characters pass
 * through unchanged, except ASCII punctuation, which moves to the code points
 * FM fonts draw it at (note: Latin letters still render as Sinhala glyphs in
 * an FM font, so use splitForFM() and draw Latin runs with a normal font).
 */
export function unicodeToFM(text: string): string {
  const s = text.normalize('NFC');
  const n = s.length;
  let out = '';
  let i = 0;

  const marks = (j: number): number => {
    while (j < n) {
      if (s[j] === 'ං') out += FM_ANUSVARA;
      else if (s[j] === 'ඃ') out += FM_VISARGA;
      else break;
      j++;
    }
    return j;
  };

  while (i < n) {
    const ch = s[i];

    if (consMap.has(ch)) {
      let base = ch;
      let j = i + 1;
      let repaya = false;
      // Repaya: ර ් ZWJ C
      if (ch === 'ර' && s[j] === HAL && s[j + 1] === ZWJ && consMap.has(s[j + 2] ?? '')) {
        repaya = true;
        base = s[j + 2];
        j += 3;
      }
      // Touching conjunct with its own FM form: ක ් ZWJ ෂ -> "CI"
      if (s[j] === HAL && s[j + 1] === ZWJ && conjMap.has(base + HAL + ZWJ + (s[j + 2] ?? ''))) {
        base = base + HAL + ZWJ + s[j + 2];
        j += 3;
      }
      // Rakaransaya / yansaya: C ් ZWJ ර|ය
      let mods = '';
      while (s[j] === HAL && s[j + 1] === ZWJ && (s[j + 2] === 'ර' || s[j + 2] === 'ය')) {
        mods += s[j + 2] === 'ර' ? FM_RAKARANSAYA : FM_YANSAYA;
        j += 3;
      }
      const cluster = (conjMap.get(base) ?? consMap.get(base)!) + mods + (repaya ? FM_REPAYA : '');
      const sign = s[j];
      const pre = sign !== undefined ? preMap.get(sign) : undefined;
      if (pre) {
        // ම් has a single glyph in FM fonts, so ේ on it is the kombuva plus that glyph (fï), not f + ම + a.
        const special = !mods && !repaya && pre[1] === 'a' ? specialMap.get(base + HAL) : undefined;
        out += special !== undefined ? pre[0] + special : pre[0] + cluster + pre[1];
        j++;
      } else if (sign !== undefined && vsMap.has(sign)) {
        const special = !mods && !repaya ? specialMap.get(base + sign) : undefined;
        out += special ?? cluster + vsMap.get(sign)!;
        j++;
        // Touching-letter ZWJ after al-lakuna has no FM equivalent: drop it.
        if (sign === HAL && s[j] === ZWJ) j++;
      } else {
        out += cluster;
      }
      i = marks(j);
      continue;
    }

    const iv = ivMap.get(ch);
    if (iv !== undefined) {
      out += iv;
      i = marks(i + 1);
      continue;
    }

    if (ch === ZWJ || ch === ZWNJ) {
      i++;
      continue;
    }
    // Stray signs (malformed input) - map them as-is; punctuation to its FM slot.
    const pre = preMap.get(ch);
    if (pre) out += pre[0] + pre[1];
    else if (ch === 'ං') out += FM_ANUSVARA;
    else if (ch === 'ඃ') out += FM_VISARGA;
    else out += vsMap.get(ch) ?? punctMap.get(ch) ?? ch;
    i++;
  }
  return out;
}

// ---- FM -> Unicode --------------------------------------------------------

type TokKind = 'cons' | 'iv' | 'sign' | 'pre' | 'mod' | 'repaya' | 'mark';
interface Tok { kind: TokKind; u: string }

/** Split a Unicode syllable (from the table) into decoder tokens. */
function decompose(u: string): Tok[] {
  const toks: Tok[] = [];
  const n = u.length;
  let i = 0;
  while (i < n) {
    const ch = u[i];
    if (consMap.has(ch)) {
      let cons = ch;
      i++;
      const mods: Tok[] = [];
      while (i + 2 < n && u[i] === HAL && u[i + 1] === ZWJ && consMap.has(u[i + 2])) {
        const c2 = u[i + 2];
        if (c2 === 'ර' || c2 === 'ය') mods.push({ kind: 'mod', u: HAL + ZWJ + c2 });
        else cons += HAL + ZWJ + c2;
        i += 3;
      }
      toks.push({ kind: 'cons', u: cons }, ...mods);
    } else if (ivMap.has(ch)) {
      toks.push({ kind: 'iv', u: ch });
      i++;
    } else if (vsMap.has(ch) || preMap.has(ch)) {
      toks.push({ kind: 'sign', u: ch });
      i++;
    } else {
      toks.push({ kind: 'mark', u: ch });
      i++;
    }
  }
  return toks;
}

/** Reverse table, longest FM sequence first (ties keep table order). */
const reverseTable: readonly (readonly [string, readonly Tok[]])[] = (() => {
  const t = new Map<string, Tok[]>();
  const add = (f: string, toks: Tok[]) => { if (!t.has(f)) t.set(f, toks); };
  for (const [u, f] of FM_CONSONANTS) add(f, [{ kind: 'cons', u }]);
  for (const [u, f] of FM_SPECIAL_SYLLABLES) add(f, decompose(u));
  for (const [u, f] of FM_CONJUNCTS) add(f, [{ kind: 'cons', u }]);
  for (const [u, f] of FM_INDEPENDENT_VOWELS) add(f, [{ kind: 'iv', u }]);
  for (const [u, f] of FM_VOWEL_SIGNS) add(f, [{ kind: 'sign', u }]);
  add('f', [{ kind: 'pre', u: 'ෙ' }]);
  add('ff', [{ kind: 'pre', u: 'ෛ' }]);
  add(FM_RAKARANSAYA, [{ kind: 'mod', u: HAL + ZWJ + 'ර' }]);
  add(FM_YANSAYA, [{ kind: 'mod', u: HAL + ZWJ + 'ය' }]);
  add(FM_REPAYA, [{ kind: 'repaya', u: 'ර' + HAL + ZWJ }]);
  add(FM_ANUSVARA, [{ kind: 'mark', u: 'ං' }]);
  add(FM_VISARGA, [{ kind: 'mark', u: 'ඃ' }]);
  for (const [u, f] of FM_PUNCTUATION) add(f, [{ kind: 'mark', u }]);
  for (const [f, u] of table.decodeAliases) add(f, decompose(u));
  return [...t.entries()].sort((a, b) => b[0].length - a[0].length);
})();

function tokenizeFM(text: string): Tok[] {
  const toks: Tok[] = [];
  let i = 0;
  outer: while (i < text.length) {
    for (const [f, ts] of reverseTable) {
      if (text.startsWith(f, i)) {
        for (const t of ts) toks.push({ ...t });
        i += f.length;
        continue outer;
      }
    }
    toks.push({ kind: 'mark', u: text[i] }); // passthrough (spaces, digits, ...)
    i++;
  }
  return toks;
}

/** Convert FM-encoded text back to Unicode Sinhala. */
export function fmToUnicode(text: string): string {
  const toks = tokenizeFM(text);
  let out = '';
  let k = 0;
  const kind = (j: number): TokKind | '' => toks[j]?.kind ?? '';

  /** Read a consonant cluster starting at toks[k0] (a 'cons'). Returns [unicode, nextIndex]. */
  const readCluster = (k0: number): [string, number] => {
    let cluster = toks[k0].u;
    let rep = false;
    let m = k0 + 1;
    for (;;) {
      if (kind(m) === 'repaya') { rep = true; m++; }
      else if (kind(m) === 'mod') { cluster += toks[m].u; m++; }
      else if (kind(m) === 'sign' && toks[m].u === HAL && kind(m + 1) === 'mod') {
        // "a%" typed instead of "%a": al-lakuna before rakaransaya
        [toks[m], toks[m + 1]] = [toks[m + 1], toks[m]];
      } else break;
    }
    return [(rep ? 'ර' + HAL + ZWJ : '') + cluster, m];
  };

  while (k < toks.length) {
    const t = toks[k];
    if (t.kind === 'pre' && kind(k + 1) === 'cons') {
      const [cluster, m0] = readCluster(k + 1);
      let m = m0;
      let sign = t.u;
      if (t.u === 'ෙ') {
        const a = kind(m) === 'sign' ? toks[m].u : '';
        const b = kind(m + 1) === 'sign' ? toks[m + 1].u : '';
        if (a === 'ා' && b === HAL) { sign = 'ෝ'; m += 2; }
        else if (a === 'ා') { sign = 'ො'; m++; }
        else if (a === HAL) { sign = 'ේ'; m++; }
        else if (a === 'ෟ') { sign = 'ෞ'; m++; }
      }
      out += cluster + sign;
      k = m;
    } else if (t.kind === 'cons') {
      const [cluster, m] = readCluster(k);
      out += cluster;
      k = m;
    } else {
      out += t.u;
      k++;
    }
  }
  return out.normalize('NFC');
}

// ---- Run splitting for rendering -----------------------------------------

export interface FMRun { text: string; sinhala: boolean }

/**
 * Split text into Sinhala and non-Sinhala runs. Sinhala runs should be
 * converted with unicodeToFM() and drawn with the FM font; other runs
 * (Latin, digits, punctuation) should be drawn with a normal font because in
 * FM fonts ASCII code points are Sinhala glyphs. Whitespace sticks to the
 * preceding run (or the following one at the start of the string).
 */
export function splitForFM(text: string): FMRun[] {
  const runs: FMRun[] = [];
  let pendingWs = '';
  for (const ch of text) {
    if (/\s/.test(ch)) {
      if (runs.length) runs[runs.length - 1].text += ch;
      else pendingWs += ch;
      continue;
    }
    const sinhala = isSinhalaChar(ch);
    const last = runs[runs.length - 1];
    if (last && last.sinhala === sinhala) last.text += ch;
    else runs.push({ text: (runs.length ? '' : pendingWs) + ch, sinhala });
  }
  if (!runs.length && pendingWs) runs.push({ text: pendingWs, sinhala: false });
  return runs;
}
